message.content:
{
  "css": "/* Category Heading Pill */
.task-category .category-heading {
  background-color: var(--quiet);
  border-radius: 16px;
  padding: 4px 12px;
  display: inline-flex;
}

.task-category .category-heading h2 {
  font-size: 14px;
  font-weight: 600;
  margin: 0;
  line-height: 1;
}

/* Add Task Button */
.add-task {
  width: 44px;
  height: 44px;
  min-width: 44px;
  border: none;
  background: transparent;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.add-task img {
  width: 20px;
  height: 20px;
  display: block;
}

/* Task Lists */
.task-list {
  margin-top: 8px;
  padding: 0;
  list-style: none;
}

/* Dynamic Task Row */
.task-row {
  min-height: 56px;
  display: flex;
  align-items: center;
  gap: 8px;
}

/* Task Toggle / Label */
.task-toggle {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  padding: 8px 0;
  min-height: 44px;
  cursor: pointer;
  flex: 1;
  min-width: 0;
}

/* Native Checkbox */
.task-check {
  width: 20px;
  height: 20px;
  min-width: 20px;
  flex-shrink: 0;
  margin-top: 2px;
  accent-color: var(--focus);
  cursor: pointer;
}

/* Task Title */
.task-name {
  font-size: 16px;
  font-weight: 500;
  line-height: 1.6;
  word-break: keep-all;
  overflow-wrap: break-word;
  color: var(--text);
}

/* Completed State */
.task-row.is-complete .task-name,
.task-check:checked + .task-name {
  color: var(--muted);
  text-decoration: line-through;
  opacity: 1;
}

/* Delete Button */
.delete-task {
  width: 44px;
  height: 44px;
  min-width: 44px;
  border: none;
  background: transparent;
  padding: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
}

.delete-task img {
  width: 20px;
  height: 20px;
  display: block;
}

/* Empty State */
#empty-state {
  font-size: 14px;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.6;
  padding-bottom: 24px;
  text-align: center;
}

/* Page Error */
#page-error {
  font-size: 14px;
  font-weight: 500;
  color: #d32f2f;
  margin-top: 16px;
}

#page-error:empty {
  display: none;
}"
}
